import sys
from itertools import combinations


def solution(pairs, prices):
	prices_map = {i: price for i, price in enumerate(prices, start=1)}
	triples = []

	for triple in combinations(range(1, len(pairs) + 1), r=3):
		score = 0
		for el in triple:
			for u, v in pairs:
				if u == el and v in triple or v == el and u in triple:
					score += 1

		if score >= 6:
			triples.append(triple)

	min_price = sys.maxsize
	for triple in triples:
		total_price = 0
		for el in triple:
			total_price += prices_map[el]

		min_price = min(total_price, min_price)

	if min_price == sys.maxsize:
		return -1

	return min_price



if __name__ == "__main__":
	n, m = map(int, input().rstrip().split(" "))
