n,m=[int(i) for i in input().split()]
price=[int(i) for i in input().split()]
from collections import defaultdict
graph=defaultdict(list)
for i in range(m):
    p,c=[int(i) for i in input().split()]
    graph[p].append(c)
    graph[c].append(p)
visited=[0]*(n+1)
pushed=[0]*(n+1)
minn=[]

def bfs(p):
    stack=[]
    stack.append(p)
    while stack:
        start=stack.pop(0)
        visited[start]=1
        for j in graph[start]:
            if not visited[j]:
                visited[j]=1
                stack.append(j)
                pushed[j]=start
            else:
                if pushed[j]==pushed[start]:
                    minn.append(price[j-1]+price[start-1]+price[pushed[j]-1])

bfs(1)
print(pushed)
if not minn:
    print(-1)
else:
    print(min(minn))
